<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Purchase extends Model { protected $fillable=['purchase_no','supplier_id','warehouse_id','user_id','status','subtotal','discount','tax','total','expected_at','ordered_at','received_at','note']; protected $casts=['subtotal'=>'decimal:2','discount'=>'decimal:2','tax'=>'decimal:2','total'=>'decimal:2','expected_at'=>'date','ordered_at'=>'datetime','received_at'=>'datetime']; public function supplier(){return $this->belongsTo(Supplier::class);} public function warehouse(){return $this->belongsTo(Warehouse::class);} public function user(){return $this->belongsTo(User::class);} public function items(){return $this->hasMany(PurchaseItem::class);} public function returns(){return $this->hasMany(PurchaseReturn::class);} }
